sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
	if (isLoading || newValue === '') {
		return;
	}

	ScriptLoader.getScripts('CustomUtils.jsdbx', function() {

		g_form.getReference('caller_id', function(caller) {
			if(CustomUtils.ToBoolean(caller.getValue('vip'))) {

				ScriptLoader.getScripts('CustomUtils.jsdbx', function() {
					var userIsVIPMessage = 'custom_user_is_vip';

					CustomUtils.i18nTranslate(
						userIsVIPMessage, 
						function(translations) {
							g_form.showFieldMsg(
								'caller_id', 
								translations[userIsVIPMessage], 
								'warning'
							);
						}
					);
				});

			} else
				g_form.hideFieldMsg('caller_id');
		});
	});
}
